package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import static com.aliothmoon.maafw.once.BingNavigationFixture.*;
public class TimedInternalTaskGuardTest {
    static final String SEARCH="com.microsoft.bing/com.microsoft.sapphire.app.search.SearchActivity";
    static String w(){return TimedTaskGuardTest.browserWindows().replace(BingNavigationSnapshot.BROWSER,SEARCH);}
    static String a(){return TimedTaskGuardTest.browserActivities().replace(BingNavigationSnapshot.BROWSER,SEARCH);}
    static BingNavigationSnapshot.TimedTaskGuard p(String w,String a){return BingNavigationSnapshot.parseTimedTaskGuard(w,a,PROFILE,RootReadOnlyAnimationGuardTest.G,TimedTaskGuardTest.original(),6000,6010);}
    @Test public void completeSearchOrOtherInternalChainIsOnlyTaskPresence(){for(String c:new String[]{SEARCH,"com.microsoft.bing/com.microsoft.sapphire.other.InternalActivity"}){var proof=p(w().replace(SEARCH,c),a().replace(SEARCH,c));assertTrue(proof.summary(),proof.matches(TimedTaskGuardTest.original(),6010));assertEquals(BingNavigationSnapshot.Status.UNKNOWN,TimedReturnSnapshotTest.parse(w().replace(SEARCH,c),a().replace(SEARCH,c)).status());}}
    @Test public void fakePrefixForeignOwnerOtherTaskOrMissingHistReject(){for(String w:new String[]{w().replace(SEARCH,"com.microsoft.bing.evil/.Activity"),w().replace("mOwnerUid=10073","mOwnerUid=10074"),w().replace("rootTaskId=15","rootTaskId=16"),w().replace("mCurrentFocus=Window{bbb","mCurrentFocus=Window{bbc")})assertFalse(p(w,a()).matches(TimedTaskGuardTest.original(),6010));assertFalse(p(w(),a().replace(activityBlock(BingNavigationSnapshot.BROWSER,"eee","15",true).replace(BingNavigationSnapshot.BROWSER,SEARCH),"")).matches(TimedTaskGuardTest.original(),6010));}
    @Test public void visibleOverlayHiddenOwnerOrActivityLinkCannotBeSkipped(){for(String w:new String[]{w()+window("other/.Overlay","abc1",true),w().replace("mActivityRecord=ActivityRecord{eee","mActivityRecord=ActivityRecord{eef"),w().replace(RootReadOnlyAnimationGuardTest.ownWindow(),RootReadOnlyAnimationGuardTest.ownWindow().replace("isVisible=false","isVisible=true"))})assertFalse(p(w,a()).matches(TimedTaskGuardTest.original(),6010));}
    @Test public void originalTemplateAnchorAndFreshnessAreStillExact(){assertFalse(p(w().replace("Window{aaa","Window{aab"),a()).matches(TimedTaskGuardTest.original(),6010));assertFalse(p(w(),a()).matches(TimedTaskGuardTest.original(),11001));assertFalse(p(w(),a().replace("A=10073:com.microsoft.bing U=0","A=10074:com.microsoft.bing U=0")).matches(TimedTaskGuardTest.original(),6010));}
}
